// ApiTokenScoped reaches ApiToken entities of one Workspace.
type ApiTokenScoped struct{ s *Scoped }

// ApiToken returns the ApiToken entities of the Workspace.
func (s *Scoped) ApiToken() *ApiTokenScoped { return &ApiTokenScoped{s: s} }

// Query returns a ApiToken query already confined to the Workspace.
func (t *ApiTokenScoped) Query() *ApiTokenQuery {
	return t.s.c.ApiToken.Query().Where(apitoken.WorkspaceID(t.s.ws))
}

// Get returns the ApiToken with the id; a row of another Workspace is not found.
func (t *ApiTokenScoped) Get(ctx context.Context, id int64) (*ApiToken, error) {
	return t.Query().Where(apitoken.ID(id)).Only(ctx)
}

