// ApiTokenScopedCreateBulk creates several ApiToken entities of one Workspace at once.
type ApiTokenScopedCreateBulk struct {
	s  *Scoped
	xs []*ApiTokenScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ApiTokenScoped) CreateBulk(xs ...*ApiTokenScopedCreate) *ApiTokenScopedCreateBulk {
	return &ApiTokenScopedCreateBulk{s: t.s, xs: xs}
}

func (b *ApiTokenScopedCreateBulk) raw(ctx context.Context) (*ApiTokenCreateBulk, error) {
	builders := make([]*ApiTokenCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("ApiToken: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.ApiToken.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the ApiToken entities.
func (b *ApiTokenScopedCreateBulk) Save(ctx context.Context) ([]*ApiToken, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*ApiToken
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeApiToken("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *ApiTokenScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

