func (x *AutomationScopedCreate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyAutomationRun(ctx, m.RunsIDs()); err != nil {
		return fmt.Errorf("runs: %w", err)
	}
	if err := x.s.verifyAutomationVersion(ctx, m.VersionsIDs()); err != nil {
		return fmt.Errorf("versions: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then creates the Automation.
func (x *AutomationScopedCreate) Save(ctx context.Context) (*Automation, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *Automation
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeAutomation("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *AutomationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// AutomationScopedCreateBulk creates several Automation entities of one Workspace at once.
type AutomationScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationScoped) CreateBulk(xs ...*AutomationScopedCreate) *AutomationScopedCreateBulk {
	return &AutomationScopedCreateBulk{s: t.s, xs: xs}
}

func (b *AutomationScopedCreateBulk) raw(ctx context.Context) (*AutomationCreateBulk, error) {
	builders := make([]*AutomationCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Automation: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Automation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Automation entities.
func (b *AutomationScopedCreateBulk) Save(ctx context.Context) ([]*Automation, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Automation
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeAutomation("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *AutomationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

