// AutomationRunScopedCreateBulk creates several AutomationRun entities of one Workspace at once.
type AutomationRunScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationRunScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationRunScoped) CreateBulk(xs ...*AutomationRunScopedCreate) *AutomationRunScopedCreateBulk {
	return &AutomationRunScopedCreateBulk{s: t.s, xs: xs}
}

func (b *AutomationRunScopedCreateBulk) raw(ctx context.Context) (*AutomationRunCreateBulk, error) {
	builders := make([]*AutomationRunCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("AutomationRun: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.AutomationRun.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the AutomationRun entities.
func (b *AutomationRunScopedCreateBulk) Save(ctx context.Context) ([]*AutomationRun, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *AutomationRunScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

