// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *BrandKitScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.BrandKit.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.BrandKit.Query().Where(brandkit.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*BrandKit, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeBrandKit("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *BrandKitScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// BroadcastScoped reaches Broadcast entities of one Workspace.
type BroadcastScoped struct{ s *Scoped }

// Broadcast returns the Broadcast entities of the Workspace.
func (s *Scoped) Broadcast() *BroadcastScoped { return &BroadcastScoped{s: s} }

// Query returns a Broadcast query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *BroadcastScoped) Query() *BroadcastQuery {
	return t.s.c.Broadcast.Query().Where(broadcast.WorkspaceID(t.s.ws), broadcast.DiscardedAtIsNil())
}

// QueryWithDiscarded returns a Broadcast query confined to the Workspace that also sees discarded rows.
func (t *BroadcastScoped) QueryWithDiscarded() *BroadcastQuery {
	return t.s.c.Broadcast.Query().Where(broadcast.WorkspaceID(t.s.ws))
}

// QueryDiscarded returns a Broadcast query confined to the Workspace that sees only discarded rows.
func (t *BroadcastScoped) QueryDiscarded() *BroadcastQuery {
	return t.QueryWithDiscarded().Where(broadcast.DiscardedAtNotNil())
}

// Get returns the Broadcast with the id, discarded or not; a row of another Workspace is not found.
func (t *BroadcastScoped) Get(ctx context.Context, id int64) (*Broadcast, error) {
	return t.QueryWithDiscarded().Where(broadcast.ID(id)).Only(ctx)
}

// Discard stamps discarded_at on the kept Broadcast with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found.
func (t *BroadcastScoped) Discard(ctx context.Context, id int64, ps ...predicate.Broadcast) error {
	return t.setDiscarded(ctx, id, true, ps)
}

// Undiscard clears discarded_at on the discarded Broadcast with the id; a row that is not
// discarded is not found.
func (t *BroadcastScoped) Undiscard(ctx context.Context, id int64) error {
	return t.setDiscarded(ctx, id, false, nil)
}

// Restore is Undiscard that leaves a kept Broadcast as it is: only a row that does not exist in the
// Workspace is not found.
func (t *BroadcastScoped) Restore(ctx context.Context, id int64) error {
	err := t.Undiscard(ctx, id)
	if !IsNotFound(err) {
		return err
	}
	_, err = t.Get(ctx, id)
	return err
}

func (t *BroadcastScoped) setDiscarded(ctx context.Context, id int64, discard bool, ps []predicate.Broadcast) error {
	where := append([]predicate.Broadcast{broadcast.ID(id), broadcast.WorkspaceID(t.s.ws)}, ps...)
	if discard {
		where = append(where, broadcast.DiscardedAtIsNil())
	} else {
		where = append(where, broadcast.DiscardedAtNotNil())
	}
	write := func(c *Client) (*Broadcast, error) {
		u := c.Broadcast.UpdateOneID(id).Where(where...)
		if discard {
			u.SetDiscardedAt(time.Now())
		} else {
			u.ClearDiscardedAt()
		}
		return u.Save(ctx)
	}
	if t.s.auditing() {
		verb := "restore"
		if discard {
			verb = "discard"
		}
		return t.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Broadcast.Query().Where(where...).Only(ctx)
			if err != nil {
				return err
			}
			after, err := write(ts.c)
			if err != nil {
				return err
			}
			return ts.record(ctx, auditChangeBroadcast(verb, before, after))
		})
	}
	_, err := write(t.s.c)
	return err
}

// BroadcastScopedDeleteOne wraps BroadcastDeleteOne.
type BroadcastScopedDeleteOne struct {
	s *Scoped
	b *BroadcastDeleteOne
}

// PurgeOneID physically removes the Broadcast with the id; a row of another Workspace is not found.
func (t *BroadcastScoped) PurgeOneID(id int64) *BroadcastScopedDeleteOne {
	return &BroadcastScopedDeleteOne{s: t.s, b: t.s.c.Broadcast.DeleteOneID(id).Where(broadcast.WorkspaceID(t.s.ws))}
}

// Where appends predicates the row must also match (fencing).
func (x *BroadcastScopedDeleteOne) Where(ps ...predicate.Broadcast) *BroadcastScopedDeleteOne {
	x.b.Where(ps...)
	return x
}

// Exec deletes the row; a missing row is a NotFoundError.
func (x *BroadcastScopedDeleteOne) Exec(ctx context.Context) error {
	if x.s.auditing() {
		return x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Broadcast.Query().Where(x.b._d.mutation.predicates...).Only(ctx)
			if err != nil {
				return err
			}
			x.b._d.auditRebind(ts.c)
			if err := x.b.Exec(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeBroadcast("delete", before, nil))
		})
	}
	return x.b.Exec(ctx)
}

// BroadcastScopedDelete wraps BroadcastDelete.
type BroadcastScopedDelete struct {
	s *Scoped
	b *BroadcastDelete
}

// Purge physically removes the Broadcast entities of the Workspace that match the predicates.
func (t *BroadcastScoped) Purge() *BroadcastScopedDelete {
	return &BroadcastScopedDelete{s: t.s, b: t.s.c.Broadcast.Delete().Where(broadcast.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *BroadcastScopedDelete) Where(ps ...predicate.Broadcast) *BroadcastScopedDelete {
	x.b.Where(ps...)
	return x
}

// Exec deletes the rows and returns how many were deleted.
func (x *BroadcastScopedDelete) Exec(ctx context.Context) (int, error) {
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			rows, err := ts.c.Broadcast.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Exec(ctx); err != nil {
				return err
			}
			for _, row := range rows {
				if err := ts.record(ctx, auditChangeBroadcast("delete", row, nil)); err != nil {
					return err
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Exec(ctx)
}

