// BroadcastScopedCreateBulk creates several Broadcast entities of one Workspace at once.
type BroadcastScopedCreateBulk struct {
	s  *Scoped
	xs []*BroadcastScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BroadcastScoped) CreateBulk(xs ...*BroadcastScopedCreate) *BroadcastScopedCreateBulk {
	return &BroadcastScopedCreateBulk{s: t.s, xs: xs}
}

func (b *BroadcastScopedCreateBulk) raw(ctx context.Context) (*BroadcastCreateBulk, error) {
	builders := make([]*BroadcastCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Broadcast: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Broadcast.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Broadcast entities.
func (b *BroadcastScopedCreateBulk) Save(ctx context.Context) ([]*Broadcast, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Broadcast
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeBroadcast("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *BroadcastScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

