// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *BroadcastScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(broadcast.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// BroadcastScopedUpsertOne is the "upsert" of one Broadcast.
type BroadcastScopedUpsertOne struct {
	x *BroadcastScopedCreate
	u *BroadcastUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *BroadcastScopedCreate) OnConflictColumns(columns ...string) *BroadcastScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *BroadcastScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *BroadcastScopedUpsertOne {
	return &BroadcastScopedUpsertOne{x: x, u: x.b.OnConflict((&BroadcastScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *BroadcastScopedUpsertOne) UpdateNewValues() *BroadcastScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *BroadcastScopedUpsertOne) Ignore() *BroadcastScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *BroadcastScopedUpsertOne) DoNothing() *BroadcastScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *BroadcastScopedUpsertOne) Update(set func(*BroadcastScopedUpsert)) *BroadcastScopedUpsertOne {
	u.u.Update(func(s *BroadcastUpsert) { set(&BroadcastScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *BroadcastScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *BroadcastScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *BroadcastScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.Broadcast.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeBroadcast("create", nil, row))
	})
	return id, err
}

// BroadcastScopedUpsertBulk is the "upsert" of several Broadcast entities.
type BroadcastScopedUpsertBulk struct {
	b       *BroadcastScopedCreateBulk
	t       *BroadcastScoped
	columns []string
	opts    []func(*BroadcastUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *BroadcastScopedCreateBulk) OnConflictColumns(columns ...string) *BroadcastScopedUpsertBulk {
	return &BroadcastScopedUpsertBulk{b: b, t: &BroadcastScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *BroadcastScopedUpsertBulk) UpdateNewValues() *BroadcastScopedUpsertBulk {
	u.opts = append(u.opts, func(r *BroadcastUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *BroadcastScopedUpsertBulk) Ignore() *BroadcastScopedUpsertBulk {
	u.opts = append(u.opts, func(r *BroadcastUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *BroadcastScopedUpsertBulk) DoNothing() *BroadcastScopedUpsertBulk {
	u.opts = append(u.opts, func(r *BroadcastUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *BroadcastScopedUpsertBulk) Update(set func(*BroadcastScopedUpsert)) *BroadcastScopedUpsertBulk {
	u.opts = append(u.opts, func(r *BroadcastUpsertBulk) {
		r.Update(func(s *BroadcastUpsert) { set(&BroadcastScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *BroadcastScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

