func (x *BroadcastScopedUpdateOne) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyBroadcastRecipient(ctx, m.RecipientsIDs()); err != nil {
		return fmt.Errorf("recipients: %w", err)
	}
	if err := x.s.verifySegment(ctx, m.SegmentIDs()); err != nil {
		return fmt.Errorf("segment: %w", err)
	}
	if err := x.s.verifyIntegration(ctx, m.IntegrationIDs()); err != nil {
		return fmt.Errorf("integration: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the Broadcast.
func (x *BroadcastScopedUpdateOne) Save(ctx context.Context) (*Broadcast, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *Broadcast
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.Broadcast.Query().Where(x.b.mutation.predicates...).Where(broadcast.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeBroadcast("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *BroadcastScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// BroadcastScopedUpdate wraps BroadcastUpdate: a conditional bulk update of one Workspace.
type BroadcastScopedUpdate struct {
	s *Scoped
	b *BroadcastUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Broadcast entities of the Workspace that match the predicates.
func (t *BroadcastScoped) Update() *BroadcastScopedUpdate {
	return &BroadcastScopedUpdate{s: t.s, b: t.s.c.Broadcast.Update().Where(broadcast.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *BroadcastScopedUpdate) Where(ps ...predicate.Broadcast) *BroadcastScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *BroadcastScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *BroadcastScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(broadcast.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

