func (x *BroadcastScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyBroadcastRecipient(ctx, m.RecipientsIDs()); err != nil {
		return fmt.Errorf("recipients: %w", err)
	}
	if err := x.s.verifySegment(ctx, m.SegmentIDs()); err != nil {
		return fmt.Errorf("segment: %w", err)
	}
	if err := x.s.verifyIntegration(ctx, m.IntegrationIDs()); err != nil {
		return fmt.Errorf("integration: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *BroadcastScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Broadcast.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.Broadcast.Query().Where(broadcast.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*Broadcast, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeBroadcast("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *BroadcastScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

