// ---------------------------------------------------------------- create bulk

// ConfirmationScopedCreateBulk creates several Confirmation entities of one Workspace at once.
type ConfirmationScopedCreateBulk struct {
	s  *Scoped
	xs []*ConfirmationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ConfirmationScoped) CreateBulk(xs ...*ConfirmationScopedCreate) *ConfirmationScopedCreateBulk {
	return &ConfirmationScopedCreateBulk{s: t.s, xs: xs}
}

func (b *ConfirmationScopedCreateBulk) raw(ctx context.Context) (*ConfirmationCreateBulk, error) {
	builders := make([]*ConfirmationCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Confirmation: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Confirmation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Confirmation entities.
func (b *ConfirmationScopedCreateBulk) Save(ctx context.Context) ([]*Confirmation, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *ConfirmationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

