func (u *ConfirmationScopedUpsert) UpdateContactID() *ConfirmationScopedUpsert {
	u.u.SetExcluded(confirmation.FieldContactID)
	return u
}

// ClearContactID clears the value of the "contact_id" field.
func (u *ConfirmationScopedUpsert) ClearContactID() *ConfirmationScopedUpsert {
	u.u.SetNull(confirmation.FieldContactID)
	return u
}

// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *ConfirmationScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(confirmation.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// ConfirmationScopedUpsertOne is the "upsert" of one Confirmation.
type ConfirmationScopedUpsertOne struct {
	x *ConfirmationScopedCreate
	u *ConfirmationUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *ConfirmationScopedCreate) OnConflictColumns(columns ...string) *ConfirmationScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *ConfirmationScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *ConfirmationScopedUpsertOne {
	return &ConfirmationScopedUpsertOne{x: x, u: x.b.OnConflict((&ConfirmationScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *ConfirmationScopedUpsertOne) UpdateNewValues() *ConfirmationScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *ConfirmationScopedUpsertOne) Ignore() *ConfirmationScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *ConfirmationScopedUpsertOne) DoNothing() *ConfirmationScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *ConfirmationScopedUpsertOne) Update(set func(*ConfirmationScopedUpsert)) *ConfirmationScopedUpsertOne {
	u.u.Update(func(s *ConfirmationUpsert) { set(&ConfirmationScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *ConfirmationScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *ConfirmationScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

// ConfirmationScopedUpsertBulk is the "upsert" of several Confirmation entities.
type ConfirmationScopedUpsertBulk struct {
	b       *ConfirmationScopedCreateBulk
	t       *ConfirmationScoped
	columns []string
	opts    []func(*ConfirmationUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *ConfirmationScopedCreateBulk) OnConflictColumns(columns ...string) *ConfirmationScopedUpsertBulk {
	return &ConfirmationScopedUpsertBulk{b: b, t: &ConfirmationScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *ConfirmationScopedUpsertBulk) UpdateNewValues() *ConfirmationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ConfirmationUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *ConfirmationScopedUpsertBulk) Ignore() *ConfirmationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ConfirmationUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *ConfirmationScopedUpsertBulk) DoNothing() *ConfirmationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ConfirmationUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *ConfirmationScopedUpsertBulk) Update(set func(*ConfirmationScopedUpsert)) *ConfirmationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ConfirmationUpsertBulk) {
		r.Update(func(s *ConfirmationUpsert) { set(&ConfirmationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *ConfirmationScopedUpsertBulk) Exec(ctx context.Context) error {
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

