// ContactScopedCreateBulk creates several Contact entities of one Workspace at once.
type ContactScopedCreateBulk struct {
	s  *Scoped
	xs []*ContactScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ContactScoped) CreateBulk(xs ...*ContactScopedCreate) *ContactScopedCreateBulk {
	return &ContactScopedCreateBulk{s: t.s, xs: xs}
}

func (b *ContactScopedCreateBulk) raw(ctx context.Context) (*ContactCreateBulk, error) {
	builders := make([]*ContactCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Contact: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Contact.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Contact entities.
func (b *ContactScopedCreateBulk) Save(ctx context.Context) ([]*Contact, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Contact
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeContact("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *ContactScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

