// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *ContactScopedUpsertBulk) DoNothing() *ContactScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ContactUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *ContactScopedUpsertBulk) Update(set func(*ContactScopedUpsert)) *ContactScopedUpsertBulk {
	u.opts = append(u.opts, func(r *ContactUpsertBulk) {
		r.Update(func(s *ContactUpsert) { set(&ContactScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *ContactScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

