// ---------------------------------------------------------------- create bulk

// CustomFieldScopedCreateBulk creates several CustomField entities of one Workspace at once.
type CustomFieldScopedCreateBulk struct {
	s  *Scoped
	xs []*CustomFieldScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *CustomFieldScoped) CreateBulk(xs ...*CustomFieldScopedCreate) *CustomFieldScopedCreateBulk {
	return &CustomFieldScopedCreateBulk{s: t.s, xs: xs}
}

func (b *CustomFieldScopedCreateBulk) raw(ctx context.Context) (*CustomFieldCreateBulk, error) {
	builders := make([]*CustomFieldCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("CustomField: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.CustomField.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the CustomField entities.
func (b *CustomFieldScopedCreateBulk) Save(ctx context.Context) ([]*CustomField, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*CustomField
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeCustomField("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *CustomFieldScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

