// ---------------------------------------------------------------- create bulk

// EventScopedCreateBulk creates several Event entities of one Workspace at once.
type EventScopedCreateBulk struct {
	s  *Scoped
	xs []*EventScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *EventScoped) CreateBulk(xs ...*EventScopedCreate) *EventScopedCreateBulk {
	return &EventScopedCreateBulk{s: t.s, xs: xs}
}

func (b *EventScopedCreateBulk) raw(ctx context.Context) (*EventCreateBulk, error) {
	builders := make([]*EventCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Event: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Event.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Event entities.
func (b *EventScopedCreateBulk) Save(ctx context.Context) ([]*Event, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *EventScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

