// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *EventScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(event.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// EventScopedUpsertOne is the "upsert" of one Event.
type EventScopedUpsertOne struct {
	x *EventScopedCreate
	u *EventUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *EventScopedCreate) OnConflictColumns(columns ...string) *EventScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *EventScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *EventScopedUpsertOne {
	return &EventScopedUpsertOne{x: x, u: x.b.OnConflict((&EventScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *EventScopedUpsertOne) UpdateNewValues() *EventScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *EventScopedUpsertOne) Ignore() *EventScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *EventScopedUpsertOne) DoNothing() *EventScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *EventScopedUpsertOne) Update(set func(*EventScopedUpsert)) *EventScopedUpsertOne {
	u.u.Update(func(s *EventUpsert) { set(&EventScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *EventScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *EventScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

// EventScopedUpsertBulk is the "upsert" of several Event entities.
type EventScopedUpsertBulk struct {
	b       *EventScopedCreateBulk
	t       *EventScoped
	columns []string
	opts    []func(*EventUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *EventScopedCreateBulk) OnConflictColumns(columns ...string) *EventScopedUpsertBulk {
	return &EventScopedUpsertBulk{b: b, t: &EventScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *EventScopedUpsertBulk) UpdateNewValues() *EventScopedUpsertBulk {
	u.opts = append(u.opts, func(r *EventUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *EventScopedUpsertBulk) Ignore() *EventScopedUpsertBulk {
	u.opts = append(u.opts, func(r *EventUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *EventScopedUpsertBulk) DoNothing() *EventScopedUpsertBulk {
	u.opts = append(u.opts, func(r *EventUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *EventScopedUpsertBulk) Update(set func(*EventScopedUpsert)) *EventScopedUpsertBulk {
	u.opts = append(u.opts, func(r *EventUpsertBulk) {
		r.Update(func(s *EventUpsert) { set(&EventScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *EventScopedUpsertBulk) Exec(ctx context.Context) error {
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

