func (x *HoldScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *HoldScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Hold.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.Hold.Query().Where(hold.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*Hold, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeHold("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *HoldScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// IntegrationScoped reaches Integration entities of one Workspace.
type IntegrationScoped struct{ s *Scoped }

// Integration returns the Integration entities of the Workspace.
func (s *Scoped) Integration() *IntegrationScoped { return &IntegrationScoped{s: s} }

// Query returns a Integration query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *IntegrationScoped) Query() *IntegrationQuery {
	return t.s.c.Integration.Query().Where(integration.WorkspaceID(t.s.ws), integration.DiscardedAtIsNil())
}

// QueryWithDiscarded returns a Integration query confined to the Workspace that also sees discarded rows.
func (t *IntegrationScoped) QueryWithDiscarded() *IntegrationQuery {
	return t.s.c.Integration.Query().Where(integration.WorkspaceID(t.s.ws))
}

// QueryDiscarded returns a Integration query confined to the Workspace that sees only discarded rows.
func (t *IntegrationScoped) QueryDiscarded() *IntegrationQuery {
	return t.QueryWithDiscarded().Where(integration.DiscardedAtNotNil())
}

// Get returns the Integration with the id, discarded or not; a row of another Workspace is not found.
func (t *IntegrationScoped) Get(ctx context.Context, id int64) (*Integration, error) {
	return t.QueryWithDiscarded().Where(integration.ID(id)).Only(ctx)
}

// Discard stamps discarded_at on the kept Integration with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found.
func (t *IntegrationScoped) Discard(ctx context.Context, id int64, ps ...predicate.Integration) error {
	return t.setDiscarded(ctx, id, true, ps)
}

// Undiscard clears discarded_at on the discarded Integration with the id; a row that is not
// discarded is not found.
func (t *IntegrationScoped) Undiscard(ctx context.Context, id int64) error {
	return t.setDiscarded(ctx, id, false, nil)
}

// Restore is Undiscard that leaves a kept Integration as it is: only a row that does not exist in the
// Workspace is not found.
func (t *IntegrationScoped) Restore(ctx context.Context, id int64) error {
	err := t.Undiscard(ctx, id)
	if !IsNotFound(err) {
		return err
	}
	_, err = t.Get(ctx, id)
	return err
}

func (t *IntegrationScoped) setDiscarded(ctx context.Context, id int64, discard bool, ps []predicate.Integration) error {
	where := append([]predicate.Integration{integration.ID(id), integration.WorkspaceID(t.s.ws)}, ps...)
	if discard {
		where = append(where, integration.DiscardedAtIsNil())
	} else {
		where = append(where, integration.DiscardedAtNotNil())
	}
	write := func(c *Client) (*Integration, error) {
		u := c.Integration.UpdateOneID(id).Where(where...)
		if discard {
			u.SetDiscardedAt(time.Now())
		} else {
			u.ClearDiscardedAt()
		}
		return u.Save(ctx)
	}
	if t.s.auditing() {
		verb := "restore"
		if discard {
			verb = "discard"
		}
		return t.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Integration.Query().Where(where...).Only(ctx)
			if err != nil {
				return err
			}
			after, err := write(ts.c)
			if err != nil {
				return err
			}
			return ts.record(ctx, auditChangeIntegration(verb, before, after))
		})
	}
	_, err := write(t.s.c)
	return err
}

// IntegrationScopedDeleteOne wraps IntegrationDeleteOne.
type IntegrationScopedDeleteOne struct {
	s *Scoped
	b *IntegrationDeleteOne
}

// PurgeOneID physically removes the Integration with the id; a row of another Workspace is not found.
func (t *IntegrationScoped) PurgeOneID(id int64) *IntegrationScopedDeleteOne {
	return &IntegrationScopedDeleteOne{s: t.s, b: t.s.c.Integration.DeleteOneID(id).Where(integration.WorkspaceID(t.s.ws))}
}

// Where appends predicates the row must also match (fencing).
func (x *IntegrationScopedDeleteOne) Where(ps ...predicate.Integration) *IntegrationScopedDeleteOne {
	x.b.Where(ps...)
	return x
}

// Exec deletes the row; a missing row is a NotFoundError.
func (x *IntegrationScopedDeleteOne) Exec(ctx context.Context) error {
	if x.s.auditing() {
		return x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Integration.Query().Where(x.b._d.mutation.predicates...).Only(ctx)
			if err != nil {
				return err
			}
			x.b._d.auditRebind(ts.c)
			if err := x.b.Exec(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeIntegration("delete", before, nil))
		})
	}
	return x.b.Exec(ctx)
}

// IntegrationScopedDelete wraps IntegrationDelete.
type IntegrationScopedDelete struct {
	s *Scoped
	b *IntegrationDelete
}

// Purge physically removes the Integration entities of the Workspace that match the predicates.
func (t *IntegrationScoped) Purge() *IntegrationScopedDelete {
	return &IntegrationScopedDelete{s: t.s, b: t.s.c.Integration.Delete().Where(integration.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *IntegrationScopedDelete) Where(ps ...predicate.Integration) *IntegrationScopedDelete {
	x.b.Where(ps...)
	return x
}

// Exec deletes the rows and returns how many were deleted.
func (x *IntegrationScopedDelete) Exec(ctx context.Context) (int, error) {
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			rows, err := ts.c.Integration.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Exec(ctx); err != nil {
				return err
			}
			for _, row := range rows {
				if err := ts.record(ctx, auditChangeIntegration("delete", row, nil)); err != nil {
					return err
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Exec(ctx)
}

