func (x *IntegrationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// IntegrationScopedCreateBulk creates several Integration entities of one Workspace at once.
type IntegrationScopedCreateBulk struct {
	s  *Scoped
	xs []*IntegrationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *IntegrationScoped) CreateBulk(xs ...*IntegrationScopedCreate) *IntegrationScopedCreateBulk {
	return &IntegrationScopedCreateBulk{s: t.s, xs: xs}
}

func (b *IntegrationScopedCreateBulk) raw(ctx context.Context) (*IntegrationCreateBulk, error) {
	builders := make([]*IntegrationCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Integration: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Integration.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Integration entities.
func (b *IntegrationScopedCreateBulk) Save(ctx context.Context) ([]*Integration, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Integration
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeIntegration("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *IntegrationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

