// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *IntegrationScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(integration.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// IntegrationScopedUpsertOne is the "upsert" of one Integration.
type IntegrationScopedUpsertOne struct {
	x *IntegrationScopedCreate
	u *IntegrationUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *IntegrationScopedCreate) OnConflictColumns(columns ...string) *IntegrationScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *IntegrationScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *IntegrationScopedUpsertOne {
	return &IntegrationScopedUpsertOne{x: x, u: x.b.OnConflict((&IntegrationScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *IntegrationScopedUpsertOne) UpdateNewValues() *IntegrationScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *IntegrationScopedUpsertOne) Ignore() *IntegrationScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *IntegrationScopedUpsertOne) DoNothing() *IntegrationScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *IntegrationScopedUpsertOne) Update(set func(*IntegrationScopedUpsert)) *IntegrationScopedUpsertOne {
	u.u.Update(func(s *IntegrationUpsert) { set(&IntegrationScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *IntegrationScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *IntegrationScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *IntegrationScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.Integration.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeIntegration("create", nil, row))
	})
	return id, err
}

// IntegrationScopedUpsertBulk is the "upsert" of several Integration entities.
type IntegrationScopedUpsertBulk struct {
	b       *IntegrationScopedCreateBulk
	t       *IntegrationScoped
	columns []string
	opts    []func(*IntegrationUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *IntegrationScopedCreateBulk) OnConflictColumns(columns ...string) *IntegrationScopedUpsertBulk {
	return &IntegrationScopedUpsertBulk{b: b, t: &IntegrationScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *IntegrationScopedUpsertBulk) UpdateNewValues() *IntegrationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *IntegrationUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *IntegrationScopedUpsertBulk) Ignore() *IntegrationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *IntegrationUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *IntegrationScopedUpsertBulk) DoNothing() *IntegrationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *IntegrationUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *IntegrationScopedUpsertBulk) Update(set func(*IntegrationScopedUpsert)) *IntegrationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *IntegrationUpsertBulk) {
		r.Update(func(s *IntegrationUpsert) { set(&IntegrationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *IntegrationScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

