// Save verifies the references against the Workspace, then updates the Integration.
func (x *IntegrationScopedUpdateOne) Save(ctx context.Context) (*Integration, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *Integration
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.Integration.Query().Where(x.b.mutation.predicates...).Where(integration.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeIntegration("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *IntegrationScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// IntegrationScopedUpdate wraps IntegrationUpdate: a conditional bulk update of one Workspace.
type IntegrationScopedUpdate struct {
	s *Scoped
	b *IntegrationUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Integration entities of the Workspace that match the predicates.
func (t *IntegrationScoped) Update() *IntegrationScopedUpdate {
	return &IntegrationScopedUpdate{s: t.s, b: t.s.c.Integration.Update().Where(integration.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *IntegrationScopedUpdate) Where(ps ...predicate.Integration) *IntegrationScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *IntegrationScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *IntegrationScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(integration.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

