func (x *IntegrationScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifySendLimiter(ctx, m.SendLimiterIDs()); err != nil {
		return fmt.Errorf("send_limiter: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *IntegrationScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Integration.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.Integration.Query().Where(integration.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*Integration, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeIntegration("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *IntegrationScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

