// ---------------------------------------------------------------- create bulk

// InvitationScopedCreateBulk creates several Invitation entities of one Workspace at once.
type InvitationScopedCreateBulk struct {
	s  *Scoped
	xs []*InvitationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *InvitationScoped) CreateBulk(xs ...*InvitationScopedCreate) *InvitationScopedCreateBulk {
	return &InvitationScopedCreateBulk{s: t.s, xs: xs}
}

func (b *InvitationScopedCreateBulk) raw(ctx context.Context) (*InvitationCreateBulk, error) {
	builders := make([]*InvitationCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Invitation: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Invitation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Invitation entities.
