// MembershipScopedCreateBulk creates several Membership entities of one Workspace at once.
type MembershipScopedCreateBulk struct {
	s  *Scoped
	xs []*MembershipScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *MembershipScoped) CreateBulk(xs ...*MembershipScopedCreate) *MembershipScopedCreateBulk {
	return &MembershipScopedCreateBulk{s: t.s, xs: xs}
}

func (b *MembershipScopedCreateBulk) raw(ctx context.Context) (*MembershipCreateBulk, error) {
	builders := make([]*MembershipCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Membership: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Membership.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Membership entities.
func (b *MembershipScopedCreateBulk) Save(ctx context.Context) ([]*Membership, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *MembershipScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

