// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *MembershipScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(membership.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// MembershipScopedUpsertOne is the "upsert" of one Membership.
type MembershipScopedUpsertOne struct {
	x *MembershipScopedCreate
	u *MembershipUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *MembershipScopedCreate) OnConflictColumns(columns ...string) *MembershipScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *MembershipScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *MembershipScopedUpsertOne {
	return &MembershipScopedUpsertOne{x: x, u: x.b.OnConflict((&MembershipScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *MembershipScopedUpsertOne) UpdateNewValues() *MembershipScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *MembershipScopedUpsertOne) Ignore() *MembershipScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *MembershipScopedUpsertOne) DoNothing() *MembershipScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *MembershipScopedUpsertOne) Update(set func(*MembershipScopedUpsert)) *MembershipScopedUpsertOne {
	u.u.Update(func(s *MembershipUpsert) { set(&MembershipScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *MembershipScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *MembershipScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

// MembershipScopedUpsertBulk is the "upsert" of several Membership entities.
type MembershipScopedUpsertBulk struct {
	b       *MembershipScopedCreateBulk
	t       *MembershipScoped
	columns []string
	opts    []func(*MembershipUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *MembershipScopedCreateBulk) OnConflictColumns(columns ...string) *MembershipScopedUpsertBulk {
	return &MembershipScopedUpsertBulk{b: b, t: &MembershipScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *MembershipScopedUpsertBulk) UpdateNewValues() *MembershipScopedUpsertBulk {
	u.opts = append(u.opts, func(r *MembershipUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *MembershipScopedUpsertBulk) Ignore() *MembershipScopedUpsertBulk {
	u.opts = append(u.opts, func(r *MembershipUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *MembershipScopedUpsertBulk) DoNothing() *MembershipScopedUpsertBulk {
	u.opts = append(u.opts, func(r *MembershipUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *MembershipScopedUpsertBulk) Update(set func(*MembershipScopedUpsert)) *MembershipScopedUpsertBulk {
	u.opts = append(u.opts, func(r *MembershipUpsertBulk) {
		r.Update(func(s *MembershipUpsert) { set(&MembershipScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *MembershipScopedUpsertBulk) Exec(ctx context.Context) error {
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

