func (x *OutboundMessageScopedCreate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyBroadcast(ctx, m.BroadcastIDs()); err != nil {
		return fmt.Errorf("broadcast: %w", err)
	}
	if err := x.s.verifyAutomation(ctx, m.AutomationIDs()); err != nil {
		return fmt.Errorf("automation: %w", err)
	}
	if err := x.s.verifyIntegration(ctx, m.IntegrationIDs()); err != nil {
		return fmt.Errorf("integration: %w", err)
	}
	if err := x.s.verifyBroadcastRecipient(ctx, m.BroadcastRecipientIDs()); err != nil {
		return fmt.Errorf("broadcast_recipient: %w", err)
	}
	if err := x.s.verifyAutomationRun(ctx, m.AutomationRunIDs()); err != nil {
		return fmt.Errorf("automation_run: %w", err)
	}
	if err := x.s.verifyContact(ctx, m.ContactIDs()); err != nil {
		return fmt.Errorf("contact: %w", err)
	}
	if err := x.s.verifyEmailTemplate(ctx, m.TemplateIDs()); err != nil {
		return fmt.Errorf("template: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then creates the OutboundMessage.
func (x *OutboundMessageScopedCreate) Save(ctx context.Context) (*OutboundMessage, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *OutboundMessageScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// OutboundMessageScopedCreateBulk creates several OutboundMessage entities of one Workspace at once.
type OutboundMessageScopedCreateBulk struct {
	s  *Scoped
	xs []*OutboundMessageScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *OutboundMessageScoped) CreateBulk(xs ...*OutboundMessageScopedCreate) *OutboundMessageScopedCreateBulk {
	return &OutboundMessageScopedCreateBulk{s: t.s, xs: xs}
}

func (b *OutboundMessageScopedCreateBulk) raw(ctx context.Context) (*OutboundMessageCreateBulk, error) {
	builders := make([]*OutboundMessageCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("OutboundMessage: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.OutboundMessage.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the OutboundMessage entities.
func (b *OutboundMessageScopedCreateBulk) Save(ctx context.Context) ([]*OutboundMessage, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *OutboundMessageScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

