// OutboundMessageScopedUpdate wraps OutboundMessageUpdate: a conditional bulk update of one Workspace.
type OutboundMessageScopedUpdate struct {
	s *Scoped
	b *OutboundMessageUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the OutboundMessage entities of the Workspace that match the predicates.
func (t *OutboundMessageScoped) Update() *OutboundMessageScopedUpdate {
	return &OutboundMessageScopedUpdate{s: t.s, b: t.s.c.OutboundMessage.Update().Where(outboundmessage.WorkspaceID(t.s.ws))}
}

