func (x *OutboundMessageScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyBroadcast(ctx, m.BroadcastIDs()); err != nil {
		return fmt.Errorf("broadcast: %w", err)
	}
	if err := x.s.verifyAutomation(ctx, m.AutomationIDs()); err != nil {
		return fmt.Errorf("automation: %w", err)
	}
	if err := x.s.verifyIntegration(ctx, m.IntegrationIDs()); err != nil {
		return fmt.Errorf("integration: %w", err)
	}
	if err := x.s.verifyBroadcastRecipient(ctx, m.BroadcastRecipientIDs()); err != nil {
		return fmt.Errorf("broadcast_recipient: %w", err)
	}
	if err := x.s.verifyAutomationRun(ctx, m.AutomationRunIDs()); err != nil {
		return fmt.Errorf("automation_run: %w", err)
	}
	if err := x.s.verifyContact(ctx, m.ContactIDs()); err != nil {
		return fmt.Errorf("contact: %w", err)
	}
	if err := x.s.verifyEmailTemplate(ctx, m.TemplateIDs()); err != nil {
		return fmt.Errorf("template: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *OutboundMessageScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *OutboundMessageScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// SegmentScoped reaches Segment entities of one Workspace.
type SegmentScoped struct{ s *Scoped }

// Segment returns the Segment entities of the Workspace.
func (s *Scoped) Segment() *SegmentScoped { return &SegmentScoped{s: s} }

// Query returns a Segment query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *SegmentScoped) Query() *SegmentQuery {
	return t.s.c.Segment.Query().Where(segment.WorkspaceID(t.s.ws), segment.DiscardedAtIsNil())
}

// QueryWithDiscarded returns a Segment query confined to the Workspace that also sees discarded rows.
func (t *SegmentScoped) QueryWithDiscarded() *SegmentQuery {
	return t.s.c.Segment.Query().Where(segment.WorkspaceID(t.s.ws))
}

// QueryDiscarded returns a Segment query confined to the Workspace that sees only discarded rows.
func (t *SegmentScoped) QueryDiscarded() *SegmentQuery {
	return t.QueryWithDiscarded().Where(segment.DiscardedAtNotNil())
}

// Get returns the Segment with the id, discarded or not; a row of another Workspace is not found.
func (t *SegmentScoped) Get(ctx context.Context, id int64) (*Segment, error) {
	return t.QueryWithDiscarded().Where(segment.ID(id)).Only(ctx)
}

// Discard stamps discarded_at on the kept Segment with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found.
func (t *SegmentScoped) Discard(ctx context.Context, id int64, ps ...predicate.Segment) error {
	return t.setDiscarded(ctx, id, true, ps)
}

// Undiscard clears discarded_at on the discarded Segment with the id; a row that is not
// discarded is not found.
func (t *SegmentScoped) Undiscard(ctx context.Context, id int64) error {
	return t.setDiscarded(ctx, id, false, nil)
}

// Restore is Undiscard that leaves a kept Segment as it is: only a row that does not exist in the
// Workspace is not found.
func (t *SegmentScoped) Restore(ctx context.Context, id int64) error {
	err := t.Undiscard(ctx, id)
	if !IsNotFound(err) {
		return err
	}
	_, err = t.Get(ctx, id)
	return err
}

func (t *SegmentScoped) setDiscarded(ctx context.Context, id int64, discard bool, ps []predicate.Segment) error {
	where := append([]predicate.Segment{segment.ID(id), segment.WorkspaceID(t.s.ws)}, ps...)
	if discard {
		where = append(where, segment.DiscardedAtIsNil())
	} else {
		where = append(where, segment.DiscardedAtNotNil())
	}
	write := func(c *Client) (*Segment, error) {
		u := c.Segment.UpdateOneID(id).Where(where...)
		if discard {
			u.SetDiscardedAt(time.Now())
		} else {
			u.ClearDiscardedAt()
		}
		return u.Save(ctx)
	}
	if t.s.auditing() {
		verb := "restore"
		if discard {
			verb = "discard"
		}
		return t.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Segment.Query().Where(where...).Only(ctx)
			if err != nil {
				return err
			}
			after, err := write(ts.c)
			if err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSegment(verb, before, after))
		})
	}
	_, err := write(t.s.c)
	return err
}

// SegmentScopedDeleteOne wraps SegmentDeleteOne.
type SegmentScopedDeleteOne struct {
	s *Scoped
	b *SegmentDeleteOne
}

// PurgeOneID physically removes the Segment with the id; a row of another Workspace is not found.
func (t *SegmentScoped) PurgeOneID(id int64) *SegmentScopedDeleteOne {
	return &SegmentScopedDeleteOne{s: t.s, b: t.s.c.Segment.DeleteOneID(id).Where(segment.WorkspaceID(t.s.ws))}
}

// Where appends predicates the row must also match (fencing).
func (x *SegmentScopedDeleteOne) Where(ps ...predicate.Segment) *SegmentScopedDeleteOne {
	x.b.Where(ps...)
	return x
}

// Exec deletes the row; a missing row is a NotFoundError.
func (x *SegmentScopedDeleteOne) Exec(ctx context.Context) error {
	if x.s.auditing() {
		return x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Segment.Query().Where(x.b._d.mutation.predicates...).Only(ctx)
			if err != nil {
				return err
			}
			x.b._d.auditRebind(ts.c)
			if err := x.b.Exec(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSegment("delete", before, nil))
		})
	}
	return x.b.Exec(ctx)
}

// SegmentScopedDelete wraps SegmentDelete.
type SegmentScopedDelete struct {
	s *Scoped
	b *SegmentDelete
}

// Purge physically removes the Segment entities of the Workspace that match the predicates.
func (t *SegmentScoped) Purge() *SegmentScopedDelete {
	return &SegmentScopedDelete{s: t.s, b: t.s.c.Segment.Delete().Where(segment.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *SegmentScopedDelete) Where(ps ...predicate.Segment) *SegmentScopedDelete {
	x.b.Where(ps...)
	return x
}

// Exec deletes the rows and returns how many were deleted.
func (x *SegmentScopedDelete) Exec(ctx context.Context) (int, error) {
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			rows, err := ts.c.Segment.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Exec(ctx); err != nil {
				return err
			}
			for _, row := range rows {
				if err := ts.record(ctx, auditChangeSegment("delete", row, nil)); err != nil {
					return err
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Exec(ctx)
}

