// Save verifies the references against the Workspace, then creates the Segment.
func (x *SegmentScopedCreate) Save(ctx context.Context) (*Segment, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *Segment
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSegment("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *SegmentScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// SegmentScopedCreateBulk creates several Segment entities of one Workspace at once.
type SegmentScopedCreateBulk struct {
	s  *Scoped
	xs []*SegmentScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SegmentScoped) CreateBulk(xs ...*SegmentScopedCreate) *SegmentScopedCreateBulk {
	return &SegmentScopedCreateBulk{s: t.s, xs: xs}
}

func (b *SegmentScopedCreateBulk) raw(ctx context.Context) (*SegmentCreateBulk, error) {
	builders := make([]*SegmentCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Segment: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Segment.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Segment entities.
func (b *SegmentScopedCreateBulk) Save(ctx context.Context) ([]*Segment, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Segment
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeSegment("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *SegmentScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

