// ClearDefinition clears the value of the "definition" field.
func (u *SegmentScopedUpsert) ClearDefinition() *SegmentScopedUpsert {
	u.u.SetNull(segment.FieldDefinition)
	return u
}

// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *SegmentScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(segment.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// SegmentScopedUpsertOne is the "upsert" of one Segment.
type SegmentScopedUpsertOne struct {
	x *SegmentScopedCreate
	u *SegmentUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *SegmentScopedCreate) OnConflictColumns(columns ...string) *SegmentScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *SegmentScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *SegmentScopedUpsertOne {
	return &SegmentScopedUpsertOne{x: x, u: x.b.OnConflict((&SegmentScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SegmentScopedUpsertOne) UpdateNewValues() *SegmentScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SegmentScopedUpsertOne) Ignore() *SegmentScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SegmentScopedUpsertOne) DoNothing() *SegmentScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SegmentScopedUpsertOne) Update(set func(*SegmentScopedUpsert)) *SegmentScopedUpsertOne {
	u.u.Update(func(s *SegmentUpsert) { set(&SegmentScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *SegmentScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *SegmentScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *SegmentScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.Segment.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeSegment("create", nil, row))
	})
	return id, err
}

// SegmentScopedUpsertBulk is the "upsert" of several Segment entities.
type SegmentScopedUpsertBulk struct {
	b       *SegmentScopedCreateBulk
	t       *SegmentScoped
	columns []string
	opts    []func(*SegmentUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *SegmentScopedCreateBulk) OnConflictColumns(columns ...string) *SegmentScopedUpsertBulk {
	return &SegmentScopedUpsertBulk{b: b, t: &SegmentScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SegmentScopedUpsertBulk) UpdateNewValues() *SegmentScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SegmentUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SegmentScopedUpsertBulk) Ignore() *SegmentScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SegmentUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SegmentScopedUpsertBulk) DoNothing() *SegmentScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SegmentUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SegmentScopedUpsertBulk) Update(set func(*SegmentScopedUpsert)) *SegmentScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SegmentUpsertBulk) {
		r.Update(func(s *SegmentUpsert) { set(&SegmentScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *SegmentScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

