// Save verifies the references against the Workspace, then creates the SendingDomain.
func (x *SendingDomainScopedCreate) Save(ctx context.Context) (*SendingDomain, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *SendingDomain
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSendingDomain("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *SendingDomainScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// SendingDomainScopedCreateBulk creates several SendingDomain entities of one Workspace at once.
type SendingDomainScopedCreateBulk struct {
	s  *Scoped
	xs []*SendingDomainScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SendingDomainScoped) CreateBulk(xs ...*SendingDomainScopedCreate) *SendingDomainScopedCreateBulk {
	return &SendingDomainScopedCreateBulk{s: t.s, xs: xs}
}

func (b *SendingDomainScopedCreateBulk) raw(ctx context.Context) (*SendingDomainCreateBulk, error) {
	builders := make([]*SendingDomainCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("SendingDomain: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.SendingDomain.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the SendingDomain entities.
func (b *SendingDomainScopedCreateBulk) Save(ctx context.Context) ([]*SendingDomain, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*SendingDomain
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeSendingDomain("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *SendingDomainScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

