// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *SendingDomainScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(sendingdomain.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// SendingDomainScopedUpsertOne is the "upsert" of one SendingDomain.
type SendingDomainScopedUpsertOne struct {
	x *SendingDomainScopedCreate
	u *SendingDomainUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *SendingDomainScopedCreate) OnConflictColumns(columns ...string) *SendingDomainScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *SendingDomainScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *SendingDomainScopedUpsertOne {
	return &SendingDomainScopedUpsertOne{x: x, u: x.b.OnConflict((&SendingDomainScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SendingDomainScopedUpsertOne) UpdateNewValues() *SendingDomainScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SendingDomainScopedUpsertOne) Ignore() *SendingDomainScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SendingDomainScopedUpsertOne) DoNothing() *SendingDomainScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SendingDomainScopedUpsertOne) Update(set func(*SendingDomainScopedUpsert)) *SendingDomainScopedUpsertOne {
	u.u.Update(func(s *SendingDomainUpsert) { set(&SendingDomainScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *SendingDomainScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *SendingDomainScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *SendingDomainScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.SendingDomain.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeSendingDomain("create", nil, row))
	})
	return id, err
}

// SendingDomainScopedUpsertBulk is the "upsert" of several SendingDomain entities.
type SendingDomainScopedUpsertBulk struct {
	b       *SendingDomainScopedCreateBulk
	t       *SendingDomainScoped
	columns []string
	opts    []func(*SendingDomainUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
