// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SendingDomainScopedUpsertBulk) UpdateNewValues() *SendingDomainScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SendingDomainUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SendingDomainScopedUpsertBulk) Ignore() *SendingDomainScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SendingDomainUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SendingDomainScopedUpsertBulk) DoNothing() *SendingDomainScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SendingDomainUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SendingDomainScopedUpsertBulk) Update(set func(*SendingDomainScopedUpsert)) *SendingDomainScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SendingDomainUpsertBulk) {
		r.Update(func(s *SendingDomainUpsert) { set(&SendingDomainScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *SendingDomainScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

