// Save verifies the references against the Workspace, then updates the SendingDomain.
func (x *SendingDomainScopedUpdateOne) Save(ctx context.Context) (*SendingDomain, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *SendingDomain
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.SendingDomain.Query().Where(x.b.mutation.predicates...).Where(sendingdomain.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSendingDomain("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *SendingDomainScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// SendingDomainScopedUpdate wraps SendingDomainUpdate: a conditional bulk update of one Workspace.
type SendingDomainScopedUpdate struct {
	s *Scoped
	b *SendingDomainUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the SendingDomain entities of the Workspace that match the predicates.
func (t *SendingDomainScoped) Update() *SendingDomainScopedUpdate {
	return &SendingDomainScopedUpdate{s: t.s, b: t.s.c.SendingDomain.Update().Where(sendingdomain.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *SendingDomainScopedUpdate) Where(ps ...predicate.SendingDomain) *SendingDomainScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *SendingDomainScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *SendingDomainScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(sendingdomain.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

