// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *SuppressionScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(suppression.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// SuppressionScopedUpsertOne is the "upsert" of one Suppression.
type SuppressionScopedUpsertOne struct {
	x *SuppressionScopedCreate
	u *SuppressionUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *SuppressionScopedCreate) OnConflictColumns(columns ...string) *SuppressionScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *SuppressionScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *SuppressionScopedUpsertOne {
	return &SuppressionScopedUpsertOne{x: x, u: x.b.OnConflict((&SuppressionScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SuppressionScopedUpsertOne) UpdateNewValues() *SuppressionScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SuppressionScopedUpsertOne) Ignore() *SuppressionScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SuppressionScopedUpsertOne) DoNothing() *SuppressionScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SuppressionScopedUpsertOne) Update(set func(*SuppressionScopedUpsert)) *SuppressionScopedUpsertOne {
	u.u.Update(func(s *SuppressionUpsert) { set(&SuppressionScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *SuppressionScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *SuppressionScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

// SuppressionScopedUpsertBulk is the "upsert" of several Suppression entities.
type SuppressionScopedUpsertBulk struct {
	b       *SuppressionScopedCreateBulk
	t       *SuppressionScoped
	columns []string
	opts    []func(*SuppressionUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *SuppressionScopedCreateBulk) OnConflictColumns(columns ...string) *SuppressionScopedUpsertBulk {
	return &SuppressionScopedUpsertBulk{b: b, t: &SuppressionScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SuppressionScopedUpsertBulk) UpdateNewValues() *SuppressionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SuppressionUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SuppressionScopedUpsertBulk) Ignore() *SuppressionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SuppressionUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SuppressionScopedUpsertBulk) DoNothing() *SuppressionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SuppressionUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SuppressionScopedUpsertBulk) Update(set func(*SuppressionScopedUpsert)) *SuppressionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *SuppressionUpsertBulk) {
		r.Update(func(s *SuppressionUpsert) { set(&SuppressionScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *SuppressionScopedUpsertBulk) Exec(ctx context.Context) error {
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

