func (x *TagScopedCreate) Save(ctx context.Context) (*Tag, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *Tag
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeTag("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *TagScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// TagScopedCreateBulk creates several Tag entities of one Workspace at once.
type TagScopedCreateBulk struct {
	s  *Scoped
	xs []*TagScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *TagScoped) CreateBulk(xs ...*TagScopedCreate) *TagScopedCreateBulk {
	return &TagScopedCreateBulk{s: t.s, xs: xs}
}

func (b *TagScopedCreateBulk) raw(ctx context.Context) (*TagCreateBulk, error) {
	builders := make([]*TagCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Tag: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Tag.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Tag entities.
func (b *TagScopedCreateBulk) Save(ctx context.Context) ([]*Tag, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Tag
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeTag("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *TagScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

// ---------------------------------------------------------------- upsert

// TagScopedUpsert is the "ON CONFLICT ... DO UPDATE" setter. It cannot move a row to
// another Workspace or point a reference at a value that was not verified on create.
type TagScopedUpsert struct{ u *sql.UpdateSet }

// SetUpdatedAt sets the "updated_at" field.
func (u *TagScopedUpsert) SetUpdatedAt(v time.Time) *TagScopedUpsert {
	u.u.Set(tag.FieldUpdatedAt, v)
	return u
}

// UpdateUpdatedAt sets the "updated_at" field to the value that was provided on create.
func (u *TagScopedUpsert) UpdateUpdatedAt() *TagScopedUpsert {
	u.u.SetExcluded(tag.FieldUpdatedAt)
	return u
}

// SetName sets the "name" field.
func (u *TagScopedUpsert) SetName(v string) *TagScopedUpsert {
	u.u.Set(tag.FieldName, v)
	return u
}

// UpdateName sets the "name" field to the value that was provided on create.
func (u *TagScopedUpsert) UpdateName() *TagScopedUpsert {
	u.u.SetExcluded(tag.FieldName)
	return u
}

// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *TagScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(tag.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// TagScopedUpsertOne is the "upsert" of one Tag.
type TagScopedUpsertOne struct {
	x *TagScopedCreate
	u *TagUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *TagScopedCreate) OnConflictColumns(columns ...string) *TagScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *TagScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *TagScopedUpsertOne {
	return &TagScopedUpsertOne{x: x, u: x.b.OnConflict((&TagScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *TagScopedUpsertOne) UpdateNewValues() *TagScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *TagScopedUpsertOne) Ignore() *TagScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *TagScopedUpsertOne) DoNothing() *TagScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *TagScopedUpsertOne) Update(set func(*TagScopedUpsert)) *TagScopedUpsertOne {
	u.u.Update(func(s *TagUpsert) { set(&TagScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *TagScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *TagScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *TagScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.Tag.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeTag("create", nil, row))
	})
	return id, err
}

// TagScopedUpsertBulk is the "upsert" of several Tag entities.
type TagScopedUpsertBulk struct {
	b       *TagScopedCreateBulk
	t       *TagScoped
	columns []string
	opts    []func(*TagUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *TagScopedCreateBulk) OnConflictColumns(columns ...string) *TagScopedUpsertBulk {
	return &TagScopedUpsertBulk{b: b, t: &TagScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *TagScopedUpsertBulk) UpdateNewValues() *TagScopedUpsertBulk {
	u.opts = append(u.opts, func(r *TagUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *TagScopedUpsertBulk) Ignore() *TagScopedUpsertBulk {
	u.opts = append(u.opts, func(r *TagUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *TagScopedUpsertBulk) DoNothing() *TagScopedUpsertBulk {
	u.opts = append(u.opts, func(r *TagUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *TagScopedUpsertBulk) Update(set func(*TagScopedUpsert)) *TagScopedUpsertBulk {
	u.opts = append(u.opts, func(r *TagUpsertBulk) {
		r.Update(func(s *TagUpsert) { set(&TagScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *TagScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

