func (x *TagScopedUpdate) AddContactIDs(ids ...int64) *TagScopedUpdate {
	x.b.AddContactIDs(ids...)
	return x
}

// AddContacts adds the "contacts" edges to the Contact entity.
func (x *TagScopedUpdate) AddContacts(v ...*Contact) *TagScopedUpdate {
	x.b.AddContacts(v...)
	return x
}

// ClearContacts clears the "contacts" edges to the Contact entity.
func (x *TagScopedUpdate) ClearContacts() *TagScopedUpdate {
	x.b.ClearContacts()
	return x
}

// RemoveContactIDs removes the "contacts" edge to Contact entities by IDs.
func (x *TagScopedUpdate) RemoveContactIDs(ids ...int64) *TagScopedUpdate {
	x.b.RemoveContactIDs(ids...)
	return x
}

// RemoveContacts removes "contacts" edges to Contact entities.
func (x *TagScopedUpdate) RemoveContacts(v ...*Contact) *TagScopedUpdate {
	x.b.RemoveContacts(v...)
	return x
}

func (x *TagScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyContact(ctx, m.ContactsIDs()); err != nil {
		return fmt.Errorf("contacts: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *TagScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Tag.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.Tag.Query().Where(tag.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*Tag, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeTag("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *TagScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

