// UnsubscribeScopedCreateBulk creates several Unsubscribe entities of one Workspace at once.
type UnsubscribeScopedCreateBulk struct {
	s  *Scoped
	xs []*UnsubscribeScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *UnsubscribeScoped) CreateBulk(xs ...*UnsubscribeScopedCreate) *UnsubscribeScopedCreateBulk {
	return &UnsubscribeScopedCreateBulk{s: t.s, xs: xs}
}

func (b *UnsubscribeScopedCreateBulk) raw(ctx context.Context) (*UnsubscribeCreateBulk, error) {
	builders := make([]*UnsubscribeCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Unsubscribe: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Unsubscribe.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Unsubscribe entities.
func (b *UnsubscribeScopedCreateBulk) Save(ctx context.Context) ([]*Unsubscribe, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *UnsubscribeScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

