// VisitorScopedCreateBulk creates several Visitor entities of one Workspace at once.
type VisitorScopedCreateBulk struct {
	s  *Scoped
	xs []*VisitorScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *VisitorScoped) CreateBulk(xs ...*VisitorScopedCreate) *VisitorScopedCreateBulk {
	return &VisitorScopedCreateBulk{s: t.s, xs: xs}
}

func (b *VisitorScopedCreateBulk) raw(ctx context.Context) (*VisitorCreateBulk, error) {
	builders := make([]*VisitorCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Visitor: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.Visitor.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Visitor entities.
func (b *VisitorScopedCreateBulk) Save(ctx context.Context) ([]*Visitor, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *VisitorScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

