// WebhookEndpointScopedCreateBulk creates several WebhookEndpoint entities of one Workspace at once.
type WebhookEndpointScopedCreateBulk struct {
	s  *Scoped
	xs []*WebhookEndpointScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *WebhookEndpointScoped) CreateBulk(xs ...*WebhookEndpointScopedCreate) *WebhookEndpointScopedCreateBulk {
	return &WebhookEndpointScopedCreateBulk{s: t.s, xs: xs}
}

func (b *WebhookEndpointScopedCreateBulk) raw(ctx context.Context) (*WebhookEndpointCreateBulk, error) {
	builders := make([]*WebhookEndpointCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("WebhookEndpoint: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.WebhookEndpoint.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the WebhookEndpoint entities.
func (b *WebhookEndpointScopedCreateBulk) Save(ctx context.Context) ([]*WebhookEndpoint, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*WebhookEndpoint
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeWebhookEndpoint("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *WebhookEndpointScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

