// Save verifies the references against the Workspace, then updates the WebhookEndpoint.
func (x *WebhookEndpointScopedUpdateOne) Save(ctx context.Context) (*WebhookEndpoint, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *WebhookEndpoint
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.WebhookEndpoint.Query().Where(x.b.mutation.predicates...).Where(webhookendpoint.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeWebhookEndpoint("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *WebhookEndpointScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// WebhookEndpointScopedUpdate wraps WebhookEndpointUpdate: a conditional bulk update of one Workspace.
type WebhookEndpointScopedUpdate struct {
	s *Scoped
	b *WebhookEndpointUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the WebhookEndpoint entities of the Workspace that match the predicates.
func (t *WebhookEndpointScoped) Update() *WebhookEndpointScopedUpdate {
	return &WebhookEndpointScopedUpdate{s: t.s, b: t.s.c.WebhookEndpoint.Update().Where(webhookendpoint.WorkspaceID(t.s.ws))}
}

